using System;using System.IO;using System.Linq;using System.Drawing;using System.Threading;using System.Threading.Tasks;using System.Diagnostics;using System.Collections.Generic;using System.Windows.Forms;using System.Windows.Media.Media3D;
namespace GearLab {
 public static class WebPerformanceTests {
  static void Pump(int ms){var clock=Stopwatch.StartNew();while(clock.ElapsedMilliseconds<ms){Application.DoEvents();Thread.Sleep(10);}}
  static T Get<T>(Task<T> task){var clock=Stopwatch.StartNew();while(!task.IsCompleted&&clock.Elapsed.TotalSeconds<30)Pump(10);if(!task.IsCompleted)throw new Exception("Web operation timed out");return task.GetAwaiter().GetResult();}
  static void Get(Task task){var clock=Stopwatch.StartNew();while(!task.IsCompleted&&clock.Elapsed.TotalSeconds<30)Pump(10);if(!task.IsCompleted)throw new Exception("Web operation timed out");task.GetAwaiter().GetResult();}
  static Dictionary<string,object> Info(RobotWebViewport web){return CADDocument.Serializer().DeserializeObject(CADDocument.Serializer().Deserialize<string>(Get(web.Inspect()))) as Dictionary<string,object>;}
  public static int Run(string folder){Directory.CreateDirectory(folder);Environment.SetEnvironmentVariable("GEARLAB_PROFILE_DIR",Path.GetFullPath(Path.Combine(folder,"profile")));try{using(var host=new Form{Text="GearLab performance verification",Size=new Size(900,650),ShowInTaskbar=false})using(var web=new RobotWebViewport()){host.Controls.Add(web);host.Show();host.WindowState=FormWindowState.Normal;host.Activate();var clock=Stopwatch.StartNew();while(!web.Ready&&clock.Elapsed.TotalSeconds<45)Pump(20);if(!web.Ready)throw new Exception("WebView2 did not initialize");web.Part("cube","Cube",MeshDocument.Cube().ToScene(),Matrix3D.Identity,Color.Orange);web.Fit();Pump(2000);var a=Info(web);Pump(750);var b=Info(web);long first=Convert.ToInt64(a["renderFrames"]),second=Convert.ToInt64(b["renderFrames"]);var matrix=Matrix3D.Identity;matrix.Translate(new Vector3D(30,10,0));web.Send(new{type="poses",parts=new[]{new{id="cube",matrix=RobotWebViewport.Matrix(matrix)}}});Pump(250);var pose=Info(web);web.Select("cube");Pump(150);var selected=Info(web);if(Convert.ToInt64(pose["renderFrames"])<=second||Convert.ToString(selected["selected"])!="cube")throw new Exception("Scene does not respond after idle");Get(web.SavePreview(Path.Combine(folder,"web-scene.png")));File.WriteAllText(Path.Combine(folder,"web-performance-results.json"),CADDocument.Serializer().Serialize(new{idle_interval_ms=750,idle_frames=second-first,parts=b["parts"],triangles=b["triangles"],pose_frames=Convert.ToInt64(pose["renderFrames"])-second,selected=selected["selected"],visibility=Get(web.TestScript("document.visibilityState"))}));host.Close();}return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"web-performance-error.txt"),ex.ToString());return 1;}}
 }
}
